<?php
require_once dirname(__DIR__).'/includes/functions.php';require_role(['student','counselor']);verify_csrf();$uid=(int)user()['id'];$id=(int)($_POST['id']??0);
if(isset($_POST['delete'])){$stmt=$con->prepare('DELETE FROM user_education WHERE id=? AND user_id=?');$stmt->bind_param('ii',$id,$uid);$stmt->execute();json_response(['ok'=>true,'message'=>'Education record removed.','reload'=>true]);}
$institution=trim($_POST['institution']??'');$qualification=trim($_POST['qualification']??'');$field=trim($_POST['field_of_study']??'');$start=(int)($_POST['start_year']??0);$end=(int)($_POST['end_year']??0);$current=isset($_POST['is_current'])?1:0;$year=(int)date('Y');
if(!$institution||!$qualification||$start<1950||$start>$year+1||(!$current&&($end<$start||$end>$year+10)))json_response(['ok'=>false,'message'=>'Check the institution, qualification, and study years.'],422);$endValue=$current?null:$end;
if($id){$stmt=$con->prepare('UPDATE user_education SET institution=?,qualification=?,field_of_study=?,start_year=?,end_year=?,is_current=? WHERE id=? AND user_id=?');$stmt->bind_param('sssiiiii',$institution,$qualification,$field,$start,$endValue,$current,$id,$uid);}else{$stmt=$con->prepare('INSERT INTO user_education(user_id,institution,qualification,field_of_study,start_year,end_year,is_current) VALUES(?,?,?,?,?,?,?)');$stmt->bind_param('isssiii',$uid,$institution,$qualification,$field,$start,$endValue,$current);}$stmt->execute();json_response(['ok'=>true,'message'=>'Education background saved.','reload'=>true]);
